const {chromium}=require('C:/Temp/openclaw-playwright/node_modules/playwright');
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true});try{const page=await browser.newPage({viewport:{width:1440,height:1100}});await page.goto('http://localhost:9090/#/auth/login');await page.locator('#email').fill(process.env.DOCS_QA_EMAIL);await page.locator('#password').fill(process.env.DOCS_QA_PASSWORD);await page.getByRole('button',{name:'Login submit button'}).click();await page.waitForURL(u=>!u.hash.includes('/auth/login'));await page.getByRole('link',{name:'Properties',exact:true}).click();await page.locator('.property-card').first().waitFor();const count=await page.locator('.property-card').count();await page.getByRole('textbox',{name:'Search properties'}).fill('Palmera');await page.waitForFunction(()=>document.querySelectorAll('.property-card').length===1);await page.getByRole('button',{name:'Table view',exact:true}).click();await page.locator('.property-alias-name').filter({hasText:'Palmera'}).waitFor();await page.getByRole('button',{name:'Card view',exact:true}).click();if(await page.locator('.property-card').count()!==1)throw Error('Filter lost');await page.getByRole('button',{name:/Clear filters$/}).click();await page.waitForFunction(n=>document.querySelectorAll('.property-card').length===n,count);await page.screenshot({path:'e2e-reports/properties-cards-desktop.png',fullPage:true});await page.getByRole('button',{name:'Table view',exact:true}).click();await page.screenshot({path:'e2e-reports/properties-table-desktop.png',fullPage:true});await page.getByRole('button',{name:'Card view',exact:true}).click();for(const width of [320,390,768]){await page.setViewportSize({width,height:1000});await page.reload();await page.locator('.property-card').first().waitFor();const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);if(overflow){await page.screenshot({path:'e2e-reports/properties-overflow.png',fullPage:true});console.log(await page.evaluate(()=>[...document.querySelectorAll('body *')].filter(e=>e.getBoundingClientRect().right>innerWidth).slice(0,12).map(e=>({tag:e.tagName,cls:e.className,width:e.getBoundingClientRect().width,right:e.getBoundingClientRect().right}))));throw Error('Overflow at '+width);}console.log('PASS no overflow',width);if(width===390)await page.screenshot({path:'e2e-reports/properties-cards-mobile.png',fullPage:true});}console.log('PASS views share search; clearing restores '+count+' records');}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
